#pragma once

#include <array>
#include <cstddef>

namespace namx::rt2
{

// The shapes of the RT-2's measured tables (Rt2RotaryData.h, generated by
// tools/capture/fit_rt2.py --write). Filters are 48 kHz; delays in ms; angles in turns.

// A delay curve over one turn, sampled at k/CURVE_POINTS.
inline constexpr size_t CURVE_POINTS = 256;

// Angle components per path: 1, cos, sin of 2π(θ − φ) up to this harmonic.
inline constexpr size_t DIRECT_ORDER = 3;
inline constexpr size_t REFLECTION_ORDER = 1;
inline constexpr size_t DRUM_ORDER = 3;

// Each bank's basis filters: this many taps, the first at this lag (samples at 48 kHz) re the
// path's read; negative lags are read ahead.
inline constexpr size_t DIRECT_TAPS = 128;
inline constexpr int DIRECT_LAG0 = -24;
inline constexpr size_t REFLECTION_TAPS = 48;
inline constexpr int REFLECTION_LAG0 = -12;
inline constexpr size_t DRUM_TAPS = 384;
inline constexpr int DRUM_LAG0 = -96;
inline constexpr size_t STATIC_TAPS = 600;

// A reflection off the room: d(θ) = t_ms − swing_ms·cos 2π(θ − φ).
struct Reflection
{
    float t_ms;
    float swing_ms;
    float phi;
};

// Components' filters in low rank: component c's filter is Σ_j gains[c·rank + j]·basis_j, so
// the engine filters `rank` weighted sums of the components instead of every component.
struct Bank
{
    const float* gains; // components × rank
    const float* basis; // rank × taps
    size_t rank;
};

// The high shelf after the horn, per output: what least squares leaves out of its top (fit_rt2.py
// tone). An RBJ biquad (BiquadChain.h), S = 1.
struct HornTone
{
    float shelf_hz;
    float shelf_db;
};

// One Mode's measurements. The direct paths and the reflections per output (A, B); the drum
// is the same on both (measured: within 0.1 dB), as are the drum's fixed filter.
struct ModeTables
{
    std::array<const float*, 2> direct_ms; // the direct path's delay per horn angle
    std::array<float, 2> direct_phi; // its angle components' zero
    const Reflection* reflections;
    size_t reflection_count;
    const float* drum_ms;
    float drum_phi;
    std::array<Bank, 2> direct;
    std::array<Bank, 2> reflection; // the reflections' components, reflection by reflection
    Bank drum;
    std::array<const float*, 2> horn_static;
    const float* drum_static;
    // The crossover ahead of the rotors (the filters were fitted to its output): a 4th-order
    // Butterworth high-pass to the horn, low-pass to the drum.
    float horn_hp_hz;
    float drum_lp_hz;
    std::array<HornTone, 2> horn_tone;
};

} // namespace namx::rt2
